  'ENSONIQ BASS':'BASS','HOLLOW LEAD':'LEAD','BREATH VOICE':'VOICE','GLASS BELL':'BELLS','CHIFF PLUCK':'PLUCK','METAL STAB':'FX',
  // curated
  'FNKBS2':'BASS','ALPHA2':'PAD','STEREO':'PAD','AIRPNO':'KEYS','HARP':'PLUCK','DREAMY':'PAD','MYVIBE':'BELLS','STLGUT':'PLUCK',
  'ICYORG':'ORGAN','ELPNO4':'KEYS','LEAD-D':'LEAD','ANGELS':'VOICE','PSTEEL':'PLUCK','MELTS':'PAD','BEGONE':'FX','KATZ':'FX',
  'HITZ':'FX','SAMPLE':'FX','CLAV 2':'KEYS','BAZURD':'BASS','HARPSI':'KEYS','COMEIN':'PAD','TRUMP1':'BRASS','PIANO':'KEYS',
  'PHOTON':'FX','PLKBOM':'PLUCK','XMAS':'BELLS','LOVSTR':'STRINGS','GATED':'FX','GRVYRD':'FX','PNBOCH':'KEYS','SNOGZ':'FX',
  'BECAUS':'PAD','SMOKIN':'LEAD','SUITAR':'PLUCK','RINGZ':'BELLS','THORNZ':'FX','LOSTRG':'STRINGS','LEAD 1':'LEAD','ACRDON':'ORGAN',
  // factory / factory 5
  'PIANO1':'KEYS','MRIMBA':'BELLS','HORN(T':'BRASS','BO STR':'STRINGS','DIGPNO':'KEYS','WAVBEL':'BELLS','ORGAN':'ORGAN',
  'ANABRS':'BRASS','VELBAS':'BASS',"'AIR'":'PAD','BOTTLS':'FX','ORCBEL':'BELLS','REED':'BRASS','2 COOL':'LEAD','BNDBEL':'BELLS',
  'BASS#0':'BASS','BASIC':'LEAD','GONG1':'BELLS','ANSYN1':'LEAD','"EOWW"':'FX','PIANO2':'KEYS','ELEPNO':'KEYS','SYNLED':'LEAD',
