  'K+SIMS':'DRUMS','ORGAN1':'ORGAN','SLDRUM':'DRUMS','SLOSTR':'STRINGS','MIXED':'PAD','SINPAD':'PAD','CLAV #':'KEYS',
  'HEVBRS':'BRASS','SYNBAZ':'BASS','SNAPS1':'DRUMS','BRASTR':'BRASS','SAX #':'BRASS','MOODS':'PAD','HI-RES':'PAD','ECHO#':'FX',
